[AUTH role=USER]
[GQL-OP list_cancelled]
query {
  returns(storeId: "{{STORE_ID}}", first: 5, statuses: ["Cancelled"]) {
    totalCount
    pageInfo { hasNextPage hasPreviousPage startCursor endCursor }
    items { id status }
  }
}
[GQL-EXEC list_cancelled]

[AUTH role=USER]
[GQL-OP before]
query {
  returnableItems(orderId: "@td(RETURNS_ORDER_B_OUTSIDE_WINDOW.id)") {
    orderLineItemId isReturnable ineligibilityReason deliveryDate returnableUntil
  }
}
[GQL-EXEC before]
[GQL-CAPTURE before.data.returnableItems.0.returnableUntil → BEFORE_UNTIL]
[AUTH role=ADMIN_DEFAULT]
[REST-OP narrow_window]
POST {{BACK_URL}}/api/platform/settings/v2/tenant/Store/{{STORE_ID}}/values
Content-Type: application/json
Body: {"Return.WindowDays": 35}
[REST-EXEC narrow_window]
[REST-OP reset_narrow_window]
POST {{BACK_URL}}/api/platform-cache/reset
[REST-EXEC reset_narrow_window]
[AUTH role=USER]
[GQL-OP poll_35]
query {
  returnableItems(orderId: "@td(RETURNS_ORDER_B_OUTSIDE_WINDOW.id)") {
    orderLineItemId isReturnable ineligibilityReason deliveryDate returnableUntil
  }
}
[GQL-EXEC poll_35]
[WAIT until=poll_35 timeout=60 interval=5] data.returnableItems.0.returnableUntil matches /^(?!{{BEFORE_UNTIL}}$).+/
[AUTH role=ADMIN_DEFAULT]
[REST-OP widen_window]
POST {{BACK_URL}}/api/platform/settings/v2/tenant/Store/{{STORE_ID}}/values
Content-Type: application/json
Body: {"Return.WindowDays": 60}
[REST-EXEC widen_window]
[REST-OP reset_widen_window]
POST {{BACK_URL}}/api/platform-cache/reset
[REST-EXEC reset_widen_window]
[AUTH role=USER]
[GQL-OP poll_after]
query {
  returnableItems(orderId: "@td(RETURNS_ORDER_B_OUTSIDE_WINDOW.id)") {
    orderLineItemId isReturnable ineligibilityReason deliveryDate returnableUntil
  }
}
[GQL-EXEC poll_after]
[WAIT until=poll_after timeout=60 interval=5] data.returnableItems.0.isReturnable = true
[AUTH role=ADMIN_DEFAULT]
[REST-OP restore_window]
POST {{BACK_URL}}/api/platform/settings/v2/tenant/Store/{{STORE_ID}}/values
Content-Type: application/json
Body: {"Return.WindowDays": 30}
[REST-EXEC restore_window]
[REST-OP reset_restore_window]
POST {{BACK_URL}}/api/platform-cache/reset
[REST-EXEC reset_restore_window]
[AUTH role=USER]
[GQL-OP poll_restored]
query {
  returnableItems(orderId: "@td(RETURNS_ORDER_B_OUTSIDE_WINDOW.id)") {
    orderLineItemId isReturnable ineligibilityReason returnableUntil
  }
}
[GQL-EXEC poll_restored]
[WAIT until=poll_restored timeout=60 interval=5] data.returnableItems.0.isReturnable = false

